    snprintf(cfg_value, sizeof(cfg_value), "%d", value);
    ndpi_set_config(ndpi_info_mod, "tls", "dpi.heuristics", cfg_value);
    value = fuzzed_data.ConsumeIntegralInRange(0, 255 + 1);
